VALUES('13eb055fe09e4caab1cfb0a4ee3e04b9','公募产品单一证券或证券投资基金投资限额(穿透后)','LIMIT_TRAN','${GMZDDDZZQHJJCTH}/${GZQSZHZZQTZJJSZ}','SUPERVISION','01,02,03','DAYTIME,DAYEND', null , '{"threshold_1":{"op":">","value":"27.0000","unit":"PERCENT","is_model":"02"}}' , '{"threshold_1":{"op":">","value":"30.0000","unit":"PERCENT","is_model":"02"}}'  , '{"threshold_1":{"op":">","unit":"PERCENT","is_model":"02"}}' , 'N' , null , '01' , null ,'system',null,sysdate,'system',sysdate, '03' , null , null , null  , null , null  , 'Y' , '《商业银行理财业务监督管理办法》第41条   商业银行理财产品直接或间接投资于银行间市场、证券交易所市场或者国务院银行业监督管理机构认可的其他证券的，应当符合以下要求：  （一）每只公募理财产品持有单只证券或单只公募证券投资基金的市值不得超过该理财产品净资产的10%；  （二）商业银行全部公募理财产品持有单只证券或单只公募证券投资基金的市值，不得超过该证券市值或该公募证券投资基金市值的30%；  （三）商业银行全部理财产品持有单一上市公司发行的股票，不得超过该上市公司可流通股票的30%。  国务院银行业监督管理机构另有规定的除外。  非因商业银行主观因素导致突破前述比例限制的，商业银行应当在流' , 'SUP061051' );
